/** The steps of the agent workflow, each with the interfaces that perform it: the entry points of the describe summary. */
export const WORKFLOW: NonNullable<DescribeData['entryPoints']> = [
  {
    "step": "Orient on what this build supports and what each kind of proof establishes",
    "interfaces": [
      "loom.describe"
    ]
  },
  {
    "step": "Identify the workspace and the requested outcome, and read the context, constraints, evidence and unresolved decisions of the task",
    "interfaces": [
      "loom.context"
    ]
  },
  {
    "step": "Preview a change through the owning model, then apply it against the same revision",
    "interfaces": [
      "loom.planChange",
      "loom.mutate"
    ]
  },
  {
    "step": "Check readiness for the actual task and implement only the scope its work package permits",
    "interfaces": [
      "loom.checkReadiness"
    ]
  },
  {
    "step": "Regenerate the artifacts from the model and check them for drift",
    "interfaces": [
      "loom.projectAll",
      "the command 'check'"
    ]
  },
  {
    "step": "Qualify the real implementation and bind its evidence to the exact inputs",
    "interfaces": [
      "the command 'qualify'",
      "the command 'evidence'"
    ]
  }
];

